function kruskal(n, edges){
  var parent=[]; for(var i=0;i<n;i++) parent.push(i);
  function find(x){ while(parent[x]!==x){ parent[x]=parent[parent[x]]; x=parent[x]; } return x; }
  function uni(a,b){ var ra=find(a),rb=find(b); if(ra===rb) return false; parent[ra]=rb; return true; }
  var sorted=edges.slice().sort(function(a,b){return a[2]-b[2];});
  var mst=[], tw=0;
  for(var i=0;i<sorted.length;i++){ var e=sorted[i];
    if(uni(e[0],e[1])){ mst.push(e); tw+=e[2]; } }
  return {edges:mst, weight:tw};
}
var EXPORTS = { kruskal:kruskal };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SpanningTreeForgePure = EXPORTS; }
